UPDATE runtime_operations SET status=CASE WHEN cancel_requested=1 THEN 'cancelled' WHEN ?5=1 AND attempt<max_attempts THEN 'queued' ELSE 'failed' END,available_at=CASE WHEN ?5=1 AND attempt<max_attempts AND cancel_requested=0 THEN CAST(unixepoch('subsec') * 1000000 AS INTEGER)+(retry_delay_secs*1000000) ELSE available_at END,worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,progress_percent=NULL,progress_stage=NULL,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status='running' AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER);